{
 "iri": "https://beatscript.app/ontology/concept/beatscript-2",
 "label": "BeatScript 2",
 "types": [
  "http://www.w3.org/2004/02/skos/core#Concept",
  "https://beatscript.app/ontology/ns#LanguageVersion"
 ],
 "definition": "BeatScript 2: a text is in it when its header block has the version line #! beatscript 2. Its canonical text begins with #! beatscript 2, and its program CID is the CID of the document {\"format\":2,\"text\":\"\u003ccanonical text\u003e\",\"type\":\"beatscript\"}. The current version: what fmt upgrades a program to and what the generators write."
}

{
 "iri": "https://beatscript.app/ontology/concept/product-beatscript-language",
 "label": "BeatScript language",
 "types": [
  "http://www.w3.org/2004/02/skos/core#Concept",
  "https://beatscript.app/ontology/ns#ProgrammingLanguage"
 ],
 "definition": "The language of BeatScript: whole tracks written as text, one line per deck, compiled to the Petri nets a deck runs. Small, total and deterministic: the same canonical text always has the same CID. Its documents are programs, written as .beatscript files."
}

{
 "iri": "https://beatscript.app/ontology/ns#Program",
 "label": "BeatScript program",
 "types": [
  "http://www.w3.org/2002/07/owl#Class"
 ],
 "definition": "A piece written in BeatScript: lines of text that compile to the Petri nets of a DJ deck. Identified by the CID of its canonical text, so a BeatScript 1 program and its upgrade to BeatScript 2, which play the same, are two programs: the upgrade is prov:wasRevisionOf the original, and each has its own ns:programCid and ns:inLanguageVersion.",
 "superclasses": [
  "https://beatscript.app/ontology/ns#MusicConcept"
 ],
 "close_match": [
  "https://ontology.pflow.xyz/ns#PetriNet"
 ]
}

